SELECT p.id AS position_id, p.entry_price, m.entry_quality_score, m.entry_stage, m.allocated_position_percent, s.id AS signal_id, s.latest_price, s.liquidity_status, s.order_book_stop_exposed, s.risk_reward_ratio, s.atr_percent, s.stop_loss, s.take_profit FROM paper_position p JOIN trade_signal s ON s.id=p.signal_id LEFT JOIN wallet_managed_position m ON m.entry_signal_id=p.signal_id WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id